const response = $input.first().json;
const now = new Date().toISOString();

// Check if the response is valid
let isHealthy = false;
let errorMessage = '';

try {
  // Check for HTTP error indicators
  if (response.error || response.code === 'ETIMEDOUT' || response.code === 'ECONNREFUSED') {
    isHealthy = false;
    errorMessage = response.error || response.message || `Connection error: ${response.code}`;
  } else {
    // Check if response has expected structure
    const body = response.body || response;
    if (body.apis !== undefined || body.status !== undefined) {
      isHealthy = true;
    } else {
      // Response received but unexpected structure
      isHealthy = true; // At least the endpoint is responding
    }
  }
} catch (e) {
  isHealthy = false;
  errorMessage = `Validation error: ${e.message}`;
}

return [{
  json: {
    endpoint: 'api-discovery',
    url: 'https://mmurawala.app.n8n.cloud/webhook/api-discovery',
    is_healthy: isHealthy,
    checked_at: now,
    status_code: response.statusCode || null,
    error_message: errorMessage,
    response_keys: Object.keys(response.body || response)
  }
}];

